import numpy as np

# Load the WISDM dataset into a Pandas DataFrame
def load_dataset(file_path):
    try:
        data = pd.read_csv(file_path)
        return data
    except Exception as e:
        print(f"Error loading dataset: {e}")

# Validate data integrity
def validate_data_integrity(data):
    # Check for missing values
    if data.isnull().values.any():
        print("Missing values found in the dataset.")
    else:
        print("No missing values found in the dataset.")

    # Check for duplicates
    if data.duplicated().any():
        print("Duplicate rows found in the dataset.")
    else:
        print("No duplicate rows found in the dataset.")

    # Check data type consistency
    expected_types = {
        'subject_id': np.int64,
        'activity_label': object,
        'timestamp': np.int64,
        'x': np.float64,
        'y': np.float64,
        'z': np.float64
    }
    for column, expected_type in expected_types.items():
        if data[column].dtype != expected_type:
            print(f"Data type mismatch for column '{column}'. Expected {expected_type}, got {data[column].dtype}.")
        else:
            print(f"Data type for column '{column}' is correct.")

# Count total samples classified as Walking activity
def count_walking_samples(data):
    walking_samples = data[data['activity_label'] == 'Walking']
    return len(walking_samples)

# Main function
def main():
    file_path = 'wisdm_dataset.csv'  # replace with your dataset file path
    data = load_dataset(file_path)
    validate_data_integrity(data)
    walking_samples_count = count_walking_samples(data)
    print(f"Total samples classified as Walking activity: {walking_samples_count}")

if __name__ == "__main__":
    main()

